mapper.insert:
insert into edu_student (
    student_code, student_name, phone, password, graduation_session, school, education, study_mode,
    class_id, product_id, join_time, created_at, updated_at
) values (
    #{studentCode}, #{studentName}, #{phone}, #{password}, #{graduationSession}, #{school}, #{education}, #{studyMode},
    #{classId}, #{productId}, #{joinTime}, #{createdAt}, #{updatedAt}
)

mapper.select:
select from edu_student s left join edu_class c on c.id = s.class_id left join sale_product p on p.id = s.product_id
and ( s.student_code like concat('%', #{keyword}, '%') or s.student_name like concat('%', #{keyword}, '%') or s.phone like concat('%', #{keyword}, '%') or s.school like concat('%', #{keyword}, '%') or ifnull(p.product_name, '') like concat('%', #{keyword}, '%') )
and s.study_mode = #{studyMode}
and s.class_id = #{classId}
and s.product_id = #{productId}
order by s.id desc
